cd /testbed && python - <<'PY'
import numpy as np
from sklearn.cluster import OPTICS
X = np.random.RandomState(0).randn(20, 2)
try:
    OPTICS(min_samples=0.1).fit(X)
    print('fit ok')
except Exception as e:
    import traceback; traceback.print_exc()
